using NavegacionShellMAUI.Data;
using NavegacionShellMAUI.Models;
namespace NavegacionShellMAUI.Views;
public partial class DetalleCursoPage : ContentPage, IQueryAttributable { readonly CursoRepository repo; Curso? curso; public DetalleCursoPage(CursoRepository repo){InitializeComponent();this.repo=repo;} public void ApplyQueryAttributes(IDictionary<string,object> query){curso=null;if(query.TryGetValue("id",out var raw)&&int.TryParse(Uri.UnescapeDataString(raw?.ToString()??""),out var id))curso=repo.ObtenerPorId(id);} protected override void OnAppearing(){base.OnAppearing();NotFound.IsVisible=curso is null;EditButton.IsVisible=curso is not null;if(curso is null){CourseName.Text="Curso no encontrado";Description.Text="Verifica el identificador e intenta de nuevo.";Metadata.Text="";return;}CourseName.Text=curso.Nombre;Description.Text=curso.Descripcion;Metadata.Text=$"Instructor: {curso.Instructor}\nDuración: {curso.Duracion}\nCategoría: {curso.Categoria}\nNivel: {curso.Nivel}\nCréditos: {curso.Creditos}\nIdentificador: {curso.Id}";} async void EditarClicked(object? sender,EventArgs e){if(curso is not null)await Shell.Current.GoToAsync("editarcurso",new ShellNavigationQueryParameters{{"curso",curso}});} async void RegresarClicked(object? sender,EventArgs e)=>await Shell.Current.GoToAsync(".."); }
